import { describe, it, expect } from 'vitest';
import { parseSectionRegistry, registryToSidebar } from '../lib/sections.js';

// Starlight 0.39 removed the `{ label, autogenerate }` group form; a labelled
// autogenerated group must now wrap the directory in `items: [{ autogenerate }]`
// (#144, spike B3). The built sidebar is unchanged: Starlight expands the bare
// `{ autogenerate }` item in place inside the labelled group.
const REGISTRY = parseSectionRegistry(`version: 1
sections:
  - id: context
    label: Context
    order: 10
    type: Context
`);

describe('registryToSidebar emits the Starlight 0.39+ group shape (B3)', () => {
  it('wraps the autogenerate directory in a one-item `items` array', () => {
    const sidebar = registryToSidebar(REGISTRY, ['context', 'extra'], {
      directoryPrefix: 'docs',
      warn: () => {},
    });
    expect(sidebar).toEqual([
      { label: 'Context', items: [{ autogenerate: { directory: 'docs/context' } }] },
      { label: 'Extra', items: [{ autogenerate: { directory: 'docs/extra' } }] },
    ]);
  });

  it('never emits the removed `autogenerate` key beside `label`', () => {
    const sidebar = registryToSidebar(REGISTRY, ['context'], { warn: () => {} });
    for (const group of sidebar) expect(group).not.toHaveProperty('autogenerate');
  });
});
